ucchini","Zucker","Zwiebel","Zwiebeln","Äpfel"];

/**
 * Parses a bounded positive amount in the units accepted by the ingredient form.
 * @param value Value to validate or store.
 */
function parseAmount(value) {
  if (typeof value !== 'string' || value.length > 30) return null;
  const match = value.trim().match(/^(\d+(?:[.,]\d+)?)\s*(g|ml|piece|pieces)?$/i);
  if (!match) return null;
  const amount = Number(match[1].replace(',', '.'));
  const unit = (match[2] || '').toLowerCase().replace(/^pieces?$/, '');
  return Number.isFinite(amount) && amount > 0 && amount <= 10000 ? { amount, unit } : null;
}



/**
 * Returns whether an ingredient contains a valid name and positive quantity.
 * @param entry Ingredient entry to validate.
 */
function validIngredient(entry) {
  if (typeof entry?.ingredient !== 'string') return false;
  const name = entry.ingredient.trim();
  return name.length > 0 && name.length <= 80 && /[\p{L}]/u.test(name)
    && !/[\u0000-\u001f\u007f]/u.test(name) && !!parseAmount(entry.servingSize);
}



/**
 * Normalizes a food name for exact ingredient coverage and duplicate checks.
 * @param entry Ingredient entry to validate.
 */
function foodName(entry) {
  const name = String(entry?.ingredient ?? '').trim().toLowerCase();
  return (INGREDIENT_ALIASES[name] ?? name).toLowerCase();
}



/**
 * Rejects known animal ingredients for vegetarian and vegan requests.
 * @param entry Ingredient entry to validate.
 * @param diet Selected dietary preference.
 */
function violatesDiet(entry, diet) {
  const name = foodName(entry);
  const meat = /\b(chicken|beef|pork|bacon|ham|salami|pastrami|lamb|turkey|duck|fish|salmon|tuna|shrimp|prawn|anchov\w*|gelatin\w*|lard|meat|sausage|hackfleisch|puten\w*|huhn|hühnchen|hähnchen|rind\w*|schwein\w*|speck|schinken|fisch|lachs|thunfisch|garnele\w*|wurst)\b/i;
  const dairy = /\b(egg\w*|milk|cream|butter|cheese|yogu?rt|honey|whey|casein|ghee|parmesan|mozzarella|feta|ei|eier|milch|sahne|käse|honig|joghurt|quark)\b/i;
  const plantDairy = /\b(soy|soja|oat|hafer|almond|mandel|coconut|kokos|peanut|erdnuss|cashew|vegan|plant)\w*\b/i;
  if (!['vegetarian', 'vegan'].includes(diet)) return false;
  if (meat.test(name)) return true;
  return diet === 'vegan' && dairy.test(name) && !plantDairy.test(name);
}



/**
 * Validates request choices without coercing arbitrary values to valid input.
 * @param request Validated recipe requirements.
 */
function requestErrors(request) {
  const errors = [];
  if (!Number.isInteger(request.portionsAmount) || request.portionsAmount < 1 || request.portionsAmount > 12) errors.push('Portions must be between 1 and 12.');
  if (!Number.isInteger(request.cooksAmount) || request.cooksAmount < 1 || request.cooksAmount > 3) errors.push('Cooks must be between 1 and 3.');
  if (!['quick', 'medium', 'complex'].includes(request.cookingTime)) errors.push('Invalid cooking time.');
  if (!['german', 'italian', 'japanese', 'indian', 'gourmet', 'fusion'].includes(request.cuisine)) errors.push('Invalid cuisine.');
  if (!['vegetarian', 'vegan', 'keto', 'no preferences'].includes(request.dietPreferences)) errors.push('Invalid diet preference.');
  return [...errors, ...ingredientErrors(request)];
}



/**
 * Checks ingredient bounds, duplicate names and achievable diet-compatible coverage.
 * @param request Validated recipe requirements.
 */
function ingredientErrors(request) {
  const entries = request.ingredients;
  if (!Array.isArray(entries) || entries.length < 1 || entries.length > 30) return ['Please provide between 1 and 30 ingredients.'];
  const invalid = entries.findIndex(/** Locates the input that needs correction. @param entry Submitted ingredient. */ entry => !validIngredient(entry));
  if (invalid >= 0) return [`Ingredient ${invalid + 1}: enter a nonempty name up to 80 characters and a positive amount up to 10000 in g, ml or pieces.`];
  if (new Set(entries.map(foodName)).size !== entries.length) return ['Please combine duplicate ingredients.'];
  const compatible = entries.filter(/** Checks whether the current item matches the filter. @param entry Current callback input. */ (entry) => !violatesDiet(entry, request.dietPreferences));
  return compatible.length < Math.ceil(entries.length * 0.7)
    ? ['Your ingredients do not allow 70% coverage with the selected diet. Please adjust ingredients or diet.'] : [];
}



/**
 * Builds a sanitized request context; absent proxy configuration fails closed.
 * @param item Webhook input item.
 * @param config Configuration for this operation.
 * @param now Current time in milliseconds.
 * @param statusOnly Whether only the quota endpoint is being validated.
 */
function validateRequest(item, config, now = Date.now(), statusOnly = false) {
  const request = item.body && typeof item.body === 'object' ? item.body : {};
  const errors = statusOnly ? [] : requestErrors(request);
  const inputErrorCount = errors.length;
  const ip = clientIp(item.headers ?? {}, config.trustedIpHeader);
  if (!ip) errors.push('A verified client IP is unavailable. Please contact the site operator.');
  if (!statusOnly && !/^models\/gemini-[\w.-]+$/.test(config.modelName ?? '')) errors.push('The recipe model is not configured. Please contact the site operator.');
  const dayKey = new Date(now).toISOString().slice(0, 10);
  const ipKey = ip?.replaceAll('.', '_').replaceAll(':', '_') ?? '';
  const code = errors.length > inputErrorCount ? 'BACKEND_CONFIGURATION_ERROR' : inputErrorCount ? 'INVALID_RECIPE_INPUT' : null;
  return { request: !statusOnly && !errors.length ? canonicalRequest(request) : request, ipKey, dayKey, valid: errors.length === 0, errors, code };
}



/** Normalizes accepted aliases while retaining quantities, units and preferences. @param request Valid input. */
function canonicalRequest(request) {
  return { ...request, ingredients: request.ingredients.map(/** Uses the shared English identity. @param entry Ingredient. */ entry => ({
    ...entry, ingredient: INGREDIENT_CATALOG.find(/** Finds canonical spelling. @param name Catalog name. */ name => name.toLowerCase() === foodName(entry)) ?? entry.ingredient,
  })) };
}



return [{ json: validateRequest($('Recipe Request').first().json, $input.first().json, Date.now(), true) }];

const RECIPE_COST = 3;
const IP_LIMIT = 3;
const SYSTEM_LIMIT = 12;
const RATE_WINDOW_MS = 10000;

/**
 * Validates a persisted quota counter; corrupted state must never reset silently.
 * @param value Value to validate or store.
 */
function quotaCount(value) {
  if (value === undefined) return 0;
  if (!Number.isSafeInteger(value) || value < 0) throw new Error('Invalid quota state.');
  return value;
}



/**
 * Returns a UTC-day snapshot with all counters expressed in recipes.
 * @param state Persisted quota state.
 * @param context Request identity and quota context.
 */
function quotaStatus(state, context) {
  const day = state?.days?.[context.dayKey];
  const ipUsed = quotaCount(day?.ips?.[context.ipKey]);
  const systemUsed = quotaCount(day?.used);
  return { ipLimit: IP_LIMIT, ipUsed, ipRemaining: Math.max(0, IP_LIMIT - ipUsed),
    systemLimit: SYSTEM_LIMIT, systemUsed, systemRemaining: Math.max(0, SYSTEM_LIMIT - systemUsed) };
}



/**
 * Builds a reservation proposal that can only be committed with the matching Firebase ETag.
 * @param state Persisted quota state.
 * @param context Request identity and quota context.
 * @param now Current time in milliseconds.
 */
function reserveQuota(state, context, now = Date.now()) {
  const quota = quotaStatus(state, context);
  const lastRequest = quotaCount(state?.lastRequests?.[context.ipKey]);
  if (lastRequest && now - lastRequest < RATE_WINDOW_MS) return { allowed: false, quota, detail: 'Too many requests. Please wait 10 seconds.' };
  if (quota.ipRemaining < RECIPE_COST || quota.systemRemaining < RECIPE_COST) {
    return { allowed: false, quota, detail: quota.systemRemaining < RECIPE_COST ? 'Global daily recipe capacity is exhausted. Please try again after midnight UTC.' : 'Your IP daily recipe reservation is exhausted. Please try again after midnight UTC.' };
  }
  const nextState = incrementReservation(state, context, now);
  return { allowed: true, nextState, quota: quotaStatus(nextState, context) };
}



/**
 * Copies all existing state and increments both quotas and the throttle atomically.
 * @param state Persisted quota state.
 * @param context Request identity and quota context.
 * @param now Current time in milliseconds.
 */
function incrementReservation(state, context, now) {
  const next = JSON.parse(JSON.stringify(state ?? { days: {}, lastRequests: {} }));
  next.days ??= {};
  next.lastRequests ??= {};
  const day = next.days[context.dayKey] ?? { used: 0, ips: {} };
  day.ips ??= {};
  day.used = quotaCount(day.used) + RECIPE_COST;
  day.ips[context.ipKey] = quotaCount(day.ips[context.ipKey]) + RECIPE_COST;
  next.days[context.dayKey] = day;
  next.lastRequests[context.ipKey] = now;
  return next;
}



/**
 * Rejects failed, malformed or unversioned Firebase reads before any paid operation.
 * @param response HTTP response to inspect.
 */
function quotaRead(response) {
  if (response.statusCode !== 200 || !response.headers?.etag) throw new Error('Quota storage is unavailable.');
  const state = response.body;
  if (state !== null && (!state || typeof state !== 'object' || Array.isArray(state))) throw new Error('Invalid quota state.');
  if (state !== null && (!state.days || !state.lastRequests)) throw new Error('Incomplete quota state.');
  return state;
}



const context = $('Validate Request').first().json;
return [{ json: quotaStatus(quotaRead($input.first().json), context) }];
